using System;

namespace Iryo.Reporting;

public static class VitalSequenceLinq
{
	public static VitalSequence Where(this VitalSequence source, Func<int, bool> predicate)
	{
		VitalSequence vitalSequence = new VitalSequence();
		foreach (int item in source)
		{
			if (predicate(item))
			{
				vitalSequence.Add(item);
			}
		}
		return vitalSequence;
	}

	public static VitalSequence Select(this VitalSequence source, Func<int, int> projector)
	{
		VitalSequence vitalSequence = new VitalSequence();
		foreach (int item in source)
		{
			vitalSequence.Add(projector(item));
		}
		return vitalSequence;
	}
}
